DO $dairy$
DECLARE payload jsonb := $payload$[{"language": "es", "slug": "leche-condensada-casera", "public_path": "/leche-condensada-casera", "title": "Leche condensada casera: lechera con dos ingredientes", "excerpt": "Haz leche condensada casera con leche y azúcar. Fotos del punto de reducción, rendimiento aproximado y conservación para usar tu lechera en postres.", "summary": "Leche entera y azúcar se reducen a fuego suave hasta dar una crema dulce de color marfil. Rinde unos 300 g, según cuánto evapores. Cuenta 5 minutos de preparación, 35–45 de cocción y aproximadamente 1 hora de enfriado.", "content_html": "<p>Leche entera y azúcar se reducen a fuego suave hasta dar una crema dulce de color marfil. Rinde unos 300 g, según cuánto evapores. Cuenta 5 minutos de preparación, 35–45 de cocción y aproximadamente 1 hora de enfriado.</p>", "notes": "<h3>Consejos y conservación</h3><p>Refrigera tapada y usa en 4–5 días. No tiene una concentración industrial estandarizada: prueba el espesor antes de usarla en una receta que dependa de un peso exacto de lata. No cocines latas cerradas. Ficha sin prueba de cocina propia. Contiene leche. Usa utensilios limpios y desinfectados y conserva a 4 °C o menos. No es una conserva para guardar a temperatura ambiente.</p><ul><li><a href=\"https://gingerwithspice.com/how-to-make-sweetened-condensed-milk/\">Ginger with Spice — milk reduction method</a></li><li><a href=\"https://addapinch.com/homemade-sweetened-condensed-milk-recipe/\">Add a Pinch — condensed milk technique</a></li></ul>", "ingredients": [{"name": "leche entera pasteurizada", "amount": "500", "unit": "ml"}, {"name": "azúcar blanco", "amount": "150", "unit": "g"}], "steps": [{"title": "Disuelve el azúcar", "content": "Pon leche y azúcar en una olla amplia de fondo grueso. Calienta suavemente y remueve hasta disolver; evita dejar cristales pegados a las paredes.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-01.webp", "image_alt": "Disuelve el azúcar — Leche condensada casera: lechera con dos ingredientes"}, {"title": "Reduce sin quemar", "content": "Cocina destapado a fuego bajo durante 35–45 minutos, con burbujeo suave. Remueve el fondo con frecuencia, sobre todo al final. Debe seguir marfil; si se dora mucho, el fuego está alto.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-02.webp", "image_alt": "Reduce sin quemar — Leche condensada casera: lechera con dos ingredientes"}, {"title": "Comprueba el espesor", "content": "Busca unos 300 g finales. Una gota en un plato frío debe fluir lentamente y cubrir la cuchara; aún espesará al enfriar. Si queda demasiado densa, agrega un poco de leche caliente y mezcla.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-03.webp", "image_alt": "Comprueba el espesor — Leche condensada casera: lechera con dos ingredientes"}, {"title": "Enfría y guarda", "content": "Pasa a un recipiente limpio y resistente al calor. Enfría en baño de agua fría sin mojar el contenido y lleva a la nevera antes de 2 horas. Deja enfriar aproximadamente 1 hora antes de usar.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-04.webp", "image_alt": "Enfría y guarda — Leche condensada casera: lechera con dos ingredientes"}], "category": "Postres", "course": "Postres", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 5, "cook_time_minutes": 45, "total_time_minutes": 110, "servings": 15, "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "alt": "Leche condensada casera: lechera con dos ingredientes"}], "video_urls": [], "keywords": ["Leche condensada casera: lechera con dos ingredientes"], "nutrition": {"calories": 61, "protein_g": 1.1, "carbs_g": 11.6, "fat_g": 1.1, "serving_size": "1 de 15 porciones, unos 20 g", "estimated": true, "note": "Estimación por porción; el rendimiento, la humedad y la marca cambian los valores.", "source": "USDA FoodData Central generic milk and sugar composition", "method": "515 g whole milk (61 kcal, 3.15 g protein, 4.8 g carbohydrate, 3.25 g fat /100 g) plus 150 g sugar (400 kcal and 100 g carbohydrate /100 g); divide totals by 15. Target yield 300 g; evaporation removes water, no drained liquid. Rounded."}, "seo": {"title": "Leche condensada casera: lechera con dos ingredientes", "description": "Haz leche condensada casera con leche y azúcar. Fotos del punto de reducción, rendimiento aproximado y conservación para usar tu lechera en postres.", "author": "Néstor Bastidas", "image_alt": "Leche condensada casera: lechera con dos ingredientes", "image_variants": ["https://manualdecocina.com/recetas/leche-condensada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-16x9.webp"], "faq": [{"q": "¿Es leche evaporada?", "a": "No. Esta lleva azúcar; la evaporada se reduce sin azúcar añadido."}, {"q": "¿Puedo quitar el azúcar?", "a": "Cambiarías textura y conservación. Sigue la receta separada de leche evaporada."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "en", "slug": "homemade-sweetened-condensed-milk", "public_path": "/en/homemade-sweetened-condensed-milk", "title": "Homemade sweetened condensed milk, two ingredients", "excerpt": "Make sweetened condensed milk with whole milk and sugar. Step photos explain reduction, thickness, approximate yield and refrigerator storage for desserts.", "summary": "Whole milk and sugar reduce gently to a sweet ivory cream. Yield is about 300 g, depending on evaporation. Allow 5 minutes preparation, 35–45 minutes cooking and approximately 1 hour cooling.", "content_html": "<p>Whole milk and sugar reduce gently to a sweet ivory cream. Yield is about 300 g, depending on evaporation. Allow 5 minutes preparation, 35–45 minutes cooking and approximately 1 hour cooling.</p>", "notes": "<h3>Tips and storage</h3><p>Keep covered and refrigerated; use within 4–5 days. Its concentration is not industrially standardized, so check thickness before using in recipes that rely on a precise can weight. Do not cook sealed cans. Not kitchen-tested. Contains milk. Use clean, sanitized equipment and refrigerate at 4 °C or below. This is not a shelf-stable canned product.</p><ul><li><a href=\"https://gingerwithspice.com/how-to-make-sweetened-condensed-milk/\">Ginger with Spice — milk reduction method</a></li><li><a href=\"https://addapinch.com/homemade-sweetened-condensed-milk-recipe/\">Add a Pinch — condensed milk technique</a></li></ul>", "ingredients": [{"name": "pasteurized whole milk", "amount": "500", "unit": "ml"}, {"name": "white sugar", "amount": "150", "unit": "g"}], "steps": [{"title": "Dissolve the sugar", "content": "Combine milk and sugar in a wide heavy-based saucepan. Warm gently and stir until dissolved, avoiding sugar crystals on the sides.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-01.webp", "image_alt": "Dissolve the sugar — Homemade sweetened condensed milk, two ingredients"}, {"title": "Reduce gently", "content": "Cook uncovered over low heat for 35–45 minutes with gentle bubbling. Stir the bottom regularly, especially near the end. Keep it ivory; strong browning means excessive heat.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-02.webp", "image_alt": "Reduce gently — Homemade sweetened condensed milk, two ingredients"}, {"title": "Check the thickness", "content": "Aim for about 300 g finished mixture. A drop on a cold plate should flow slowly and coat a spoon. It thickens further as it cools. If too thick, stir in a little hot milk.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-03.webp", "image_alt": "Check the thickness — Homemade sweetened condensed milk, two ingredients"}, {"title": "Cool and store", "content": "Transfer to a clean heatproof container. Cool in a cold-water bath without letting water enter, then refrigerate within 2 hours. Allow roughly 1 hour to cool before use.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-04.webp", "image_alt": "Cool and store — Homemade sweetened condensed milk, two ingredients"}], "category": "Desserts", "course": "Desserts", "cuisine": "International", "difficulty": "Easy", "prep_time_minutes": 5, "cook_time_minutes": 45, "total_time_minutes": 110, "servings": 15, "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "alt": "Homemade sweetened condensed milk, two ingredients"}], "video_urls": [], "keywords": ["Homemade sweetened condensed milk, two ingredients"], "nutrition": {"calories": 61, "protein_g": 1.1, "carbs_g": 11.6, "fat_g": 1.1, "serving_size": "1 of 15 servings, about 20 g", "estimated": true, "note": "Estimated per serving; yield, moisture and brands affect the values.", "source": "USDA FoodData Central generic milk and sugar composition", "method": "515 g whole milk (61 kcal, 3.15 g protein, 4.8 g carbohydrate, 3.25 g fat /100 g) plus 150 g sugar (400 kcal and 100 g carbohydrate /100 g); divide totals by 15. Target yield 300 g; evaporation removes water, no drained liquid. Rounded."}, "seo": {"title": "Homemade sweetened condensed milk, two ingredients", "description": "Make sweetened condensed milk with whole milk and sugar. Step photos explain reduction, thickness, approximate yield and refrigerator storage for desserts.", "author": "Néstor Bastidas", "image_alt": "Homemade sweetened condensed milk, two ingredients", "image_variants": ["https://manualdecocina.com/recetas/leche-condensada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-16x9.webp"], "faq": [{"q": "Is this evaporated milk?", "a": "No. This contains added sugar; evaporated milk is reduced without it."}, {"q": "Can I omit the sugar?", "a": "That changes texture and storage. Follow the separate evaporated-milk recipe."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "de", "slug": "gezuckerte-kondensmilch-selber-machen", "public_path": "/de/gezuckerte-kondensmilch-selber-machen", "title": "Gezuckerte Kondensmilch aus zwei Zutaten", "excerpt": "Gezuckerte Kondensmilch aus Vollmilch und Zucker selbst machen. Schrittfotos erklären Einkochen, Konsistenz, ungefähre Ausbeute und gekühlte Aufbewahrung.", "summary": "Vollmilch und Zucker werden sanft zu einer süßen elfenbeinfarbenen Creme reduziert. Je nach Verdunstung entstehen etwa 300 g. Plane 5 Minuten Vorbereitung, 35–45 Minuten Kochen und ungefähr 1 Stunde Abkühlen ein.", "content_html": "<p>Vollmilch und Zucker werden sanft zu einer süßen elfenbeinfarbenen Creme reduziert. Je nach Verdunstung entstehen etwa 300 g. Plane 5 Minuten Vorbereitung, 35–45 Minuten Kochen und ungefähr 1 Stunde Abkühlen ein.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>Abgedeckt gekühlt in 4–5 Tagen verbrauchen. Die Konzentration ist nicht industriell standardisiert; vor Rezepten mit exaktem Dosengewicht die Konsistenz prüfen. Keine geschlossenen Dosen kochen. Nicht in einer Testküche erprobt. Enthält Milch. Saubere, desinfizierte Geräte verwenden und bei höchstens 4 °C lagern. Dies ist keine ungekühlt haltbare Konserve.</p><ul><li><a href=\"https://gingerwithspice.com/how-to-make-sweetened-condensed-milk/\">Ginger with Spice — milk reduction method</a></li><li><a href=\"https://addapinch.com/homemade-sweetened-condensed-milk-recipe/\">Add a Pinch — condensed milk technique</a></li></ul>", "ingredients": [{"name": "pasteurisierte Vollmilch", "amount": "500", "unit": "ml"}, {"name": "weißer Zucker", "amount": "150", "unit": "g"}], "steps": [{"title": "Zucker auflösen", "content": "Milch und Zucker in einem breiten Topf mit dickem Boden vorsichtig erwärmen. Rühren, bis sich der Zucker löst. Keine Zuckerkristalle am Rand zurücklassen.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-01.webp", "image_alt": "Zucker auflösen — Gezuckerte Kondensmilch aus zwei Zutaten"}, {"title": "Sanft einkochen", "content": "Offen bei kleiner Hitze 35–45 Minuten leicht blubbern lassen. Besonders zum Ende regelmäßig über den Boden rühren. Die Creme soll hell bleiben; starke Bräunung zeigt zu hohe Hitze.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-02.webp", "image_alt": "Sanft einkochen — Gezuckerte Kondensmilch aus zwei Zutaten"}, {"title": "Konsistenz prüfen", "content": "Etwa 300 g Endmenge anstreben. Ein Tropfen auf einem kalten Teller soll langsam fließen und einen Löffel überziehen. Die Creme dickt beim Abkühlen nach. Zu feste Creme mit etwas heißer Milch verrühren.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-03.webp", "image_alt": "Konsistenz prüfen — Gezuckerte Kondensmilch aus zwei Zutaten"}, {"title": "Abkühlen und lagern", "content": "In ein sauberes hitzefestes Gefäß füllen. Im kalten Wasserbad abkühlen, ohne Wasser hineinzulassen, und innerhalb von 2 Stunden kalt stellen. Vor Verwendung ungefähr 1 Stunde abkühlen lassen.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-04.webp", "image_alt": "Abkühlen und lagern — Gezuckerte Kondensmilch aus zwei Zutaten"}], "category": "Desserts", "course": "Desserts", "cuisine": "International", "difficulty": "Einfach", "prep_time_minutes": 5, "cook_time_minutes": 45, "total_time_minutes": 110, "servings": 15, "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "alt": "Gezuckerte Kondensmilch aus zwei Zutaten"}], "video_urls": [], "keywords": ["Gezuckerte Kondensmilch aus zwei Zutaten"], "nutrition": {"calories": 61, "protein_g": 1.1, "carbs_g": 11.6, "fat_g": 1.1, "serving_size": "1 von 15 Portionen, etwa 20 g", "estimated": true, "note": "Schätzung pro Portion; Ausbeute, Feuchtigkeit und Produkte beeinflussen die Werte.", "source": "USDA FoodData Central generic milk and sugar composition", "method": "515 g whole milk (61 kcal, 3.15 g protein, 4.8 g carbohydrate, 3.25 g fat /100 g) plus 150 g sugar (400 kcal and 100 g carbohydrate /100 g); divide totals by 15. Target yield 300 g; evaporation removes water, no drained liquid. Rounded."}, "seo": {"title": "Gezuckerte Kondensmilch aus zwei Zutaten", "description": "Gezuckerte Kondensmilch aus Vollmilch und Zucker selbst machen. Schrittfotos erklären Einkochen, Konsistenz, ungefähre Ausbeute und gekühlte Aufbewahrung.", "author": "Néstor Bastidas", "image_alt": "Gezuckerte Kondensmilch aus zwei Zutaten", "image_variants": ["https://manualdecocina.com/recetas/leche-condensada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-16x9.webp"], "faq": [{"q": "Ist das ungesüßte Kondensmilch?", "a": "Nein. Diese Variante enthält Zucker, ungesüßte wird ohne Zucker reduziert."}, {"q": "Kann ich Zucker weglassen?", "a": "Das verändert Konsistenz und Aufbewahrung. Nutze das separate Rezept für ungesüßte Kondensmilch."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "fr", "slug": "lait-concentre-sucre-maison", "public_path": "/fr/lait-concentre-sucre-maison", "title": "Lait concentré sucré maison avec deux ingrédients", "excerpt": "Préparez du lait concentré sucré avec du lait entier et du sucre. Photos de la réduction, repères de texture, rendement approximatif et conservation au frais.", "summary": "Le lait entier et le sucre réduisent doucement en crème ivoire. Le rendement est d'environ 300 g selon l'évaporation. Prévoyez 5 minutes de préparation, 35–45 minutes de cuisson et environ 1 heure de refroidissement.", "content_html": "<p>Le lait entier et le sucre réduisent doucement en crème ivoire. Le rendement est d&#x27;environ 300 g selon l&#x27;évaporation. Prévoyez 5 minutes de préparation, 35–45 minutes de cuisson et environ 1 heure de refroidissement.</p>", "notes": "<h3>Conseils et conservation</h3><p>Gardez couvert au frais et consommez sous 4–5 jours. La concentration n&#x27;est pas standardisée comme en industrie : vérifiez la texture pour les recettes dépendant d&#x27;un poids précis de boîte. Ne cuisez pas de boîtes fermées. Recette non testée en cuisine. Contient du lait. Utilisez du matériel propre et désinfecté et conservez à 4 °C maximum. Cette préparation ne se conserve pas à température ambiante.</p><ul><li><a href=\"https://gingerwithspice.com/how-to-make-sweetened-condensed-milk/\">Ginger with Spice — milk reduction method</a></li><li><a href=\"https://addapinch.com/homemade-sweetened-condensed-milk-recipe/\">Add a Pinch — condensed milk technique</a></li></ul>", "ingredients": [{"name": "lait entier pasteurisé", "amount": "500", "unit": "ml"}, {"name": "sucre blanc", "amount": "150", "unit": "g"}], "steps": [{"title": "Dissolvez le sucre", "content": "Réunissez lait et sucre dans une casserole large à fond épais. Chauffez doucement en remuant jusqu'à dissolution, sans laisser de cristaux sur les parois.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-01.webp", "image_alt": "Dissolvez le sucre — Lait concentré sucré maison avec deux ingrédients"}, {"title": "Faites réduire doucement", "content": "Cuisez à découvert à feu doux pendant 35–45 minutes, à petits bouillons. Remuez régulièrement le fond, surtout à la fin. Le mélange doit rester ivoire ; une forte coloration indique trop de chaleur.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-02.webp", "image_alt": "Faites réduire doucement — Lait concentré sucré maison avec deux ingrédients"}, {"title": "Vérifiez la texture", "content": "Visez environ 300 g de préparation. Une goutte sur une assiette froide doit couler lentement et napper une cuillère. Le mélange épaissit encore au froid. Trop épais, détendez-le avec un peu de lait chaud.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-03.webp", "image_alt": "Vérifiez la texture — Lait concentré sucré maison avec deux ingrédients"}, {"title": "Refroidissez et conservez", "content": "Versez dans un récipient propre résistant à la chaleur. Refroidissez au bain d'eau froide sans entrée d'eau et réfrigérez avant 2 heures. Comptez environ 1 heure de refroidissement avant utilisation.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-04.webp", "image_alt": "Refroidissez et conservez — Lait concentré sucré maison avec deux ingrédients"}], "category": "Desserts", "course": "Desserts", "cuisine": "Internationale", "difficulty": "Facile", "prep_time_minutes": 5, "cook_time_minutes": 45, "total_time_minutes": 110, "servings": 15, "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "alt": "Lait concentré sucré maison avec deux ingrédients"}], "video_urls": [], "keywords": ["Lait concentré sucré maison avec deux ingrédients"], "nutrition": {"calories": 61, "protein_g": 1.1, "carbs_g": 11.6, "fat_g": 1.1, "serving_size": "1 des 15 portions, environ 20 g", "estimated": true, "note": "Estimation par portion ; rendement, humidité et marques modifient les valeurs.", "source": "USDA FoodData Central generic milk and sugar composition", "method": "515 g whole milk (61 kcal, 3.15 g protein, 4.8 g carbohydrate, 3.25 g fat /100 g) plus 150 g sugar (400 kcal and 100 g carbohydrate /100 g); divide totals by 15. Target yield 300 g; evaporation removes water, no drained liquid. Rounded."}, "seo": {"title": "Lait concentré sucré maison avec deux ingrédients", "description": "Préparez du lait concentré sucré avec du lait entier et du sucre. Photos de la réduction, repères de texture, rendement approximatif et conservation au frais.", "author": "Néstor Bastidas", "image_alt": "Lait concentré sucré maison avec deux ingrédients", "image_variants": ["https://manualdecocina.com/recetas/leche-condensada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-16x9.webp"], "faq": [{"q": "Est-ce du lait concentré non sucré ?", "a": "Non. Cette préparation contient du sucre ajouté."}, {"q": "Puis-je supprimer le sucre ?", "a": "Cela change texture et conservation. Suivez la recette distincte du lait concentré non sucré."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "it", "slug": "latte-condensato-fatto-in-casa", "public_path": "/it/latte-condensato-fatto-in-casa", "title": "Latte condensato fatto in casa con due ingredienti", "excerpt": "Prepara latte condensato con latte intero e zucchero. Foto della riduzione, punto di densità, resa indicativa e conservazione in frigorifero per i dolci.", "summary": "Latte intero e zucchero si riducono dolcemente in una crema color avorio. La resa è circa 300 g, secondo l'evaporazione. Calcola 5 minuti di preparazione, 35–45 di cottura e circa 1 ora per raffreddare.", "content_html": "<p>Latte intero e zucchero si riducono dolcemente in una crema color avorio. La resa è circa 300 g, secondo l&#x27;evaporazione. Calcola 5 minuti di preparazione, 35–45 di cottura e circa 1 ora per raffreddare.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Conserva coperto in frigo e usa entro 4–5 giorni. La concentrazione non è standardizzata industrialmente: controlla la densità nelle ricette basate su un peso preciso di lattina. Non cuocere lattine chiuse. Ricetta non testata in cucina. Contiene latte. Usa utensili puliti e igienizzati e conserva a 4 °C o meno. Non è una conserva da tenere a temperatura ambiente.</p><ul><li><a href=\"https://gingerwithspice.com/how-to-make-sweetened-condensed-milk/\">Ginger with Spice — milk reduction method</a></li><li><a href=\"https://addapinch.com/homemade-sweetened-condensed-milk-recipe/\">Add a Pinch — condensed milk technique</a></li></ul>", "ingredients": [{"name": "latte intero pastorizzato", "amount": "500", "unit": "ml"}, {"name": "zucchero bianco", "amount": "150", "unit": "g"}], "steps": [{"title": "Sciogli lo zucchero", "content": "Metti latte e zucchero in una casseruola larga a fondo spesso. Scalda dolcemente e mescola fino a sciogliere, evitando cristalli sulle pareti.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-01.webp", "image_alt": "Sciogli lo zucchero — Latte condensato fatto in casa con due ingredienti"}, {"title": "Fai ridurre", "content": "Cuoci scoperto a fuoco basso per 35–45 minuti, con bollicine leggere. Mescola spesso sul fondo, soprattutto alla fine. Deve restare color avorio; se scurisce molto, abbassa il fuoco.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-02.webp", "image_alt": "Fai ridurre — Latte condensato fatto in casa con due ingredienti"}, {"title": "Controlla la densità", "content": "Punta a circa 300 g finali. Una goccia su un piatto freddo deve scorrere lentamente e velare il cucchiaio. Addensa ancora raffreddando. Se troppo denso, aggiungi poco latte caldo.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-03.webp", "image_alt": "Controlla la densità — Latte condensato fatto in casa con due ingredienti"}, {"title": "Raffredda e conserva", "content": "Trasferisci in un recipiente pulito resistente al calore. Raffredda in acqua fredda senza farla entrare e metti in frigo entro 2 ore. Attendi circa 1 ora prima di usarlo.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-04.webp", "image_alt": "Raffredda e conserva — Latte condensato fatto in casa con due ingredienti"}], "category": "Dolci", "course": "Dolci", "cuisine": "Internazionale", "difficulty": "Facile", "prep_time_minutes": 5, "cook_time_minutes": 45, "total_time_minutes": 110, "servings": 15, "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "alt": "Latte condensato fatto in casa con due ingredienti"}], "video_urls": [], "keywords": ["Latte condensato fatto in casa con due ingredienti"], "nutrition": {"calories": 61, "protein_g": 1.1, "carbs_g": 11.6, "fat_g": 1.1, "serving_size": "1 di 15 porzioni, circa 20 g", "estimated": true, "note": "Stima per porzione; resa, umidità e prodotti possono cambiare i valori.", "source": "USDA FoodData Central generic milk and sugar composition", "method": "515 g whole milk (61 kcal, 3.15 g protein, 4.8 g carbohydrate, 3.25 g fat /100 g) plus 150 g sugar (400 kcal and 100 g carbohydrate /100 g); divide totals by 15. Target yield 300 g; evaporation removes water, no drained liquid. Rounded."}, "seo": {"title": "Latte condensato fatto in casa con due ingredienti", "description": "Prepara latte condensato con latte intero e zucchero. Foto della riduzione, punto di densità, resa indicativa e conservazione in frigorifero per i dolci.", "author": "Néstor Bastidas", "image_alt": "Latte condensato fatto in casa con due ingredienti", "image_variants": ["https://manualdecocina.com/recetas/leche-condensada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-16x9.webp"], "faq": [{"q": "È latte evaporato?", "a": "No. Qui si aggiunge zucchero; il latte evaporato si riduce senza zucchero."}, {"q": "Posso eliminare lo zucchero?", "a": "Cambieresti densità e conservazione. Segui la ricetta separata del latte evaporato."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "ja", "slug": "homemade-sweetened-condensed-milk", "public_path": "/ja/homemade-sweetened-condensed-milk", "title": "牛乳と砂糖だけで作る自家製加糖練乳", "excerpt": "牛乳と砂糖を煮詰める自家製練乳の作り方。工程写真で煮詰め方、とろみの目安、出来上がり量、冷蔵保存を説明します。お菓子や飲み物に使える基本の配合です。", "summary": "全乳と砂糖を弱火で煮詰め、甘いアイボリー色のクリームにします。蒸発量により約300 gできます。準備5分、加熱35〜45分、冷却約1時間が目安です。", "content_html": "<p>全乳と砂糖を弱火で煮詰め、甘いアイボリー色のクリームにします。蒸発量により約300 gできます。準備5分、加熱35〜45分、冷却約1時間が目安です。</p>", "notes": "<h3>コツと保存</h3><p>ふたをして冷蔵し、4〜5日以内に使います。工場製品のように濃度が一定ではないため、缶の重量で配合するお菓子では固さを確認してください。密閉した缶を加熱しないでください。調理試験は行っていません。 乳を含みます。清潔に洗浄・消毒した器具を使い、4 ℃以下で冷蔵してください。常温保存用の瓶詰めではありません。</p><ul><li><a href=\"https://gingerwithspice.com/how-to-make-sweetened-condensed-milk/\">Ginger with Spice — milk reduction method</a></li><li><a href=\"https://addapinch.com/homemade-sweetened-condensed-milk-recipe/\">Add a Pinch — condensed milk technique</a></li></ul>", "ingredients": [{"name": "殺菌済みの全乳", "amount": "500", "unit": "ml"}, {"name": "白砂糖", "amount": "150", "unit": "g"}], "steps": [{"title": "砂糖を溶かす", "content": "厚手の広い鍋に牛乳と砂糖を入れ、弱火で混ぜて溶かします。鍋肌に砂糖の粒を残さないようにします。", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-01.webp", "image_alt": "砂糖を溶かす — 牛乳と砂糖だけで作る自家製加糖練乳"}, {"title": "弱火で煮詰める", "content": "ふたをせず弱火で35〜45分、小さく泡立つ程度に煮ます。特に終盤は鍋底をこまめに混ぜます。色は薄いままにし、強く茶色になるなら火を弱めます。", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-02.webp", "image_alt": "弱火で煮詰める — 牛乳と砂糖だけで作る自家製加糖練乳"}, {"title": "とろみを確認する", "content": "出来上がり約300 gを目指します。冷たい皿に一滴落とすとゆっくり流れ、スプーンを薄く覆う程度が目安です。冷えるとさらに固くなります。固すぎたら温かい牛乳を少量混ぜます。", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-03.webp", "image_alt": "とろみを確認する — 牛乳と砂糖だけで作る自家製加糖練乳"}, {"title": "冷まして保存する", "content": "清潔な耐熱容器へ移します。中に水が入らないよう冷水に当て、2時間以内に冷蔵します。使う前に約1時間冷まします。", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-04.webp", "image_alt": "冷まして保存する — 牛乳と砂糖だけで作る自家製加糖練乳"}], "category": "デザート", "course": "デザート", "cuisine": "各国料理", "difficulty": "簡単", "prep_time_minutes": 5, "cook_time_minutes": 45, "total_time_minutes": 110, "servings": 15, "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "alt": "牛乳と砂糖だけで作る自家製加糖練乳"}], "video_urls": [], "keywords": ["牛乳と砂糖だけで作る自家製加糖練乳"], "nutrition": {"calories": 61, "protein_g": 1.1, "carbs_g": 11.6, "fat_g": 1.1, "serving_size": "15食分の1、約20 g", "estimated": true, "note": "1食分の推定値です。出来上がり量、水分、製品により異なります。", "source": "USDA FoodData Central generic milk and sugar composition", "method": "515 g whole milk (61 kcal, 3.15 g protein, 4.8 g carbohydrate, 3.25 g fat /100 g) plus 150 g sugar (400 kcal and 100 g carbohydrate /100 g); divide totals by 15. Target yield 300 g; evaporation removes water, no drained liquid. Rounded."}, "seo": {"title": "牛乳と砂糖だけで作る自家製加糖練乳", "description": "牛乳と砂糖を煮詰める自家製練乳の作り方。工程写真で煮詰め方、とろみの目安、出来上がり量、冷蔵保存を説明します。お菓子や飲み物に使える基本の配合です。", "author": "Néstor Bastidas", "image_alt": "牛乳と砂糖だけで作る自家製加糖練乳", "image_variants": ["https://manualdecocina.com/recetas/leche-condensada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-16x9.webp"], "faq": [{"q": "無糖練乳ですか。", "a": "いいえ。砂糖を加える加糖練乳です。無糖練乳は砂糖なしで煮詰めます。"}, {"q": "砂糖を抜いてもよいですか。", "a": "食感と保存条件が変わります。別の無糖練乳レシピに従ってください。"}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}, {"language": "pt", "slug": "leite-condensado-caseiro", "public_path": "/pt/leite-condensado-caseiro", "title": "Leite condensado caseiro com dois ingredientes", "excerpt": "Faça leite condensado com leite integral e açúcar. Fotos mostram a redução e o ponto, com rendimento aproximado e dicas para conservar e usar em sobremesas.", "summary": "Leite integral e açúcar reduzem em fogo baixo até virar um creme marfim. Rende cerca de 300 g, conforme a evaporação. Conte 5 minutos de preparo, 35–45 de cozimento e aproximadamente 1 hora para esfriar.", "content_html": "<p>Leite integral e açúcar reduzem em fogo baixo até virar um creme marfim. Rende cerca de 300 g, conforme a evaporação. Conte 5 minutos de preparo, 35–45 de cozimento e aproximadamente 1 hora para esfriar.</p>", "notes": "<h3>Dicas e conservação</h3><p>Conserve tampado na geladeira e use em 4–5 dias. A concentração não é padronizada industrialmente: confira a textura em receitas baseadas em peso exato de lata. Não cozinhe latas fechadas. Receita sem teste de cozinha próprio. Contém leite. Use utensílios limpos e higienizados e conserve a 4 °C ou menos. Não é uma conserva para guardar à temperatura ambiente.</p><ul><li><a href=\"https://gingerwithspice.com/how-to-make-sweetened-condensed-milk/\">Ginger with Spice — milk reduction method</a></li><li><a href=\"https://addapinch.com/homemade-sweetened-condensed-milk-recipe/\">Add a Pinch — condensed milk technique</a></li></ul>", "ingredients": [{"name": "leite integral pasteurizado", "amount": "500", "unit": "ml"}, {"name": "açúcar branco", "amount": "150", "unit": "g"}], "steps": [{"title": "Dissolva o açúcar", "content": "Coloque leite e açúcar em uma panela larga de fundo grosso. Aqueça suavemente e mexa até dissolver, evitando cristais nas laterais.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-01.webp", "image_alt": "Dissolva o açúcar — Leite condensado caseiro com dois ingredientes"}, {"title": "Reduza devagar", "content": "Cozinhe destampado em fogo baixo por 35–45 minutos, com borbulhas leves. Mexa o fundo frequentemente, sobretudo no final. Deve continuar marfim; se dourar muito, reduza o fogo.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-02.webp", "image_alt": "Reduza devagar — Leite condensado caseiro com dois ingredientes"}, {"title": "Confira o ponto", "content": "Busque cerca de 300 g finais. Uma gota no prato frio deve escorrer lentamente e cobrir a colher. Engrossa ao esfriar. Se ficar denso demais, misture um pouco de leite quente.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-03.webp", "image_alt": "Confira o ponto — Leite condensado caseiro com dois ingredientes"}, {"title": "Esfrie e guarde", "content": "Transfira para recipiente limpo e resistente ao calor. Esfrie em banho de água fria sem entrar água e leve à geladeira antes de 2 horas. Espere cerca de 1 hora para usar.", "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/paso-04.webp", "image_alt": "Esfrie e guarde — Leite condensado caseiro com dois ingredientes"}], "category": "Sobremesas", "course": "Sobremesas", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 5, "cook_time_minutes": 45, "total_time_minutes": 110, "servings": 15, "image_url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/leche-condensada-casera/portada.webp", "alt": "Leite condensado caseiro com dois ingredientes"}], "video_urls": [], "keywords": ["Leite condensado caseiro com dois ingredientes"], "nutrition": {"calories": 61, "protein_g": 1.1, "carbs_g": 11.6, "fat_g": 1.1, "serving_size": "1 de 15 porções, cerca de 20 g", "estimated": true, "note": "Estimativa por porção; rendimento, umidade e marcas alteram os valores.", "source": "USDA FoodData Central generic milk and sugar composition", "method": "515 g whole milk (61 kcal, 3.15 g protein, 4.8 g carbohydrate, 3.25 g fat /100 g) plus 150 g sugar (400 kcal and 100 g carbohydrate /100 g); divide totals by 15. Target yield 300 g; evaporation removes water, no drained liquid. Rounded."}, "seo": {"title": "Leite condensado caseiro com dois ingredientes", "description": "Faça leite condensado com leite integral e açúcar. Fotos mostram a redução e o ponto, com rendimento aproximado e dicas para conservar e usar em sobremesas.", "author": "Néstor Bastidas", "image_alt": "Leite condensado caseiro com dois ingredientes", "image_variants": ["https://manualdecocina.com/recetas/leche-condensada-casera/portada-1x1.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-4x3.webp", "https://manualdecocina.com/recetas/leche-condensada-casera/portada-16x9.webp"], "faq": [{"q": "É leite evaporado?", "a": "Não. Este leva açúcar; leite evaporado reduz sem açúcar adicionado."}, {"q": "Posso tirar o açúcar?", "a": "Isso muda textura e conservação. Siga a receita separada de leite evaporado."}], "additional_time_minutes": 60}, "published": false, "editorial_status": "ready"}]$payload$::jsonb;
foods jsonb := $foods$[]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "leche", "alias": "leche entera pasteurizada"}, {"slug": "azucar", "alias": "azúcar blanco"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),'Ingrediente para elaboraciones lácteas domésticas.','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>2 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
FOR v IN SELECT * FROM public.recipes WHERE recipe_group_id=group_id LOOP
 PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
 UPDATE public.recipes SET editorial_status='published' WHERE id=v.id;
END LOOP;
END $dairy$;
SELECT language,public_path,published FROM public.recipes WHERE recipe_group_id=(SELECT recipe_group_id FROM public.recipes WHERE language='es' AND slug='leche-condensada-casera') ORDER BY language;
